import math
filt=0.0
lastprint=-20
def control(o):
 global filt,lastprint
 h=o['hitch_deg']; th=math.radians(-h)
 cam=o['views'].get('camera')
 if not cam: return (2*h,-0.4,-23)
 sides=[[],[]]
 for b,d in cam['walls']:
  a=math.radians(b); x=d*math.cos(a); y=d*math.sin(a)
  s=-(math.cos(th)*x+math.sin(th)*y); q=-math.sin(th)*x+math.cos(th)*y
  if s>0.3: sides[0 if q<0 else 1].append((s,q))
 vals=[]
 for pts in sides:
  pts.sort()
  if not pts: continue
  val=min(pts,key=lambda p:abs(p[0]-4))[1]
  for (s1,y1),(s2,y2) in zip(pts,pts[1:]):
   if s1<=4<=s2 and s2>s1: val=y1+(y2-y1)*(4-s1)/(s2-s1); break
  vals.append(val)
 if len(vals)==2:
  mid=sum(vals)/2
  filt=0.85*filt+0.15*mid
 hd=math.degrees(math.atan2(5.2*filt,16))
 steer=max(-34,min(34,2.1*h-1.6*hd))
 if o['t']-lastprint>10:
  lastprint=o['t']; print('h',round(h,1),'centre',round(filt,2),'bay',cam.get('target_corners',[]))
 return (steer,-0.65,-23)

