def control(o):
    h=o['hitch_deg']; rx,ry=o['rig']['trailer_rear']; pts=[]
    v=o['views'].get('left_mirror')
    if v:
        ox,oy=v['origin']
        for b,d in v['walls']:
            a=math.radians(b); x=ox+d*math.cos(a); y=oy+d*math.sin(a)
            if rx-5<x<rx+1 and y>ry+1.0:
                pts.append((x,y))
    desired=0
    if len(pts)>=4:
        xm=sum(x for x,y in pts)/len(pts); ym=sum(y for x,y in pts)/len(pts)
        slope=sum((x-xm)*(y-ym) for x,y in pts)/max(.01,sum((x-xm)**2 for x,y in pts))
        yl=ym+slope*(rx-4-xm)
        desired=max(-12,min(15,math.degrees(math.atan2(yl-ry-1.9,4))))
    eq=math.degrees(math.atan2(2.5*math.sin(math.radians(h)),3.6+1.3*math.cos(math.radians(h))))
    return (max(-30,min(30,eq+2.5*(h-desired))),-0.25,64)

